/** Real loaded native hosts, isolated registry bindings and subsequent-process saved-world replay. */
@EventBusSubscriber(modid="vandorlabs")
public final class SegmentedLifecycleChecks {
 private static final BlockPos BASE=new BlockPos(3200,80,3200),SAVE=BASE.east(12);private static FixtureBlock block;private static BlockEntityType<NativeSegmentedDoorEntity> type;private static int checks,updates,previousSource,previousNative;private static boolean observerFailure;private static BlockPos denied;
 private static boolean enabled(){return System.getProperty("vandorlabs.transmitterPhase","").startsWith("segmented-lifecycle-");}
 private static void need(boolean ok,String why){checks++;if(!ok)throw new AssertionError("Segmented lifecycle: "+why);}
 private static final class FixtureBlock extends NativeSegmentedDoorBlock {FixtureBlock(){super(BlockBehaviour.Properties.of().strength(2.5F).noOcclusion().dynamicShape());}protected MapCodec<FixtureBlock> codec(){return MapCodec.unit(this);}protected BlockEntityType<?> entityType(){return type;}@Override public BlockEntity newBlockEntity(BlockPos p,BlockState s){return new Counting(p,s);}}
 private static final class Counting extends NativeSegmentedDoorEntity {Counting(BlockPos p,BlockState s){super(type,p,s);}@Override protected void publicationChanged(){updates++;need(publication().visual().settings()==settings()&&publication().motion().sequence()==sequence(),"local publication complete before observer");if(formed())for(var t:NativeSegmentedDoorLifecycle.members(roots()))need(t.publication().visual().settings()==t.settings()&&t.publication().motion().sequence()==t.sequence(),"all member snapshots complete before observer");if(observerFailure)throw new IllegalStateException("fixture observer");super.publicationChanged();}}
 @EventBusSubscriber(modid="vandorlabs",bus=EventBusSubscriber.Bus.MOD)public static final class Registration {@SubscribeEvent public static void register(net.neoforged.neoforge.registries.RegisterEvent event){if(!enabled())return;var id=ResourceLocation.fromNamespaceAndPath("vandorlabs","segmented_lifecycle_fixture");event.register(Registries.BLOCK,h->{block=new FixtureBlock();h.register(id,block);});event.register(Registries.ITEM,h->h.register(id,new BlockItem(block,new Item.Properties())));event.register(Registries.BLOCK_ENTITY_TYPE,h->{type=BlockEntityType.Builder.<NativeSegmentedDoorEntity>of((BlockPos p,BlockState s)->new Counting(p,s),block).build(null);h.register(id,type);});}}
 private static NativeSegmentedDoorEntity host(ServerLevel world,BlockPos p){return (NativeSegmentedDoorEntity)world.getBlockEntity(p);}
 private static void clock(ServerLevel world,long value){((net.minecraft.world.level.storage.ServerLevelData)world.getLevelData()).setGameTime(value);}
 private static void grid(ServerLevel world,BlockPos base,int width,int height){for(int x=-1;x<5;x++)for(int row=-1;row<5;row++)world.setBlock(base.offset(x,-row,0),Blocks.AIR.defaultBlockState(),2);updates=0;for(int x=0;x<width;x++)for(int row=0;row<height;row++)need(world.setBlock(base.offset(x,-row,0),block.defaultBlockState(),2),"actual world segment publication");for(int x=0;x<width;x++)host(world,base.east(x)).refreshColumn();}
 private static JsonArray snapshot(ServerLevel world,int width,int height){JsonArray all=new JsonArray();for(int x=0;x<width;x++)for(int row=0;row<height;row++){var t=host(world,BASE.offset(x,-row,0));var s=t.settings();JsonArray a=new JsonArray();for(int v:new int[]{t.topOffset(),t.height(),t.column(),t.columnsCount(),t.ticksPerSection(),t.texture(),t.duration(),(int)t.sequence(),s.direction,s.layout,s.activation,s.shape,s.position})a.add(v);for(boolean b:new boolean[]{t.formed(),t.configured(),t.targetOpen(),t.localRedstone(),t.signalOpens(),s.straight,s.window,s.join})a.add(b);a.add(t.initialPose());a.add(t.started());a.add(t.pose(0));all.add(a);}return all;}
 private static void compare(ServerLevel world,JsonObject source){int width=source.get("width").getAsInt(),height=source.get("height").getAsInt();var actual=snapshot(world,width,height);need(actual.equals(source.getAsJsonArray("tiles")),"actual Forge stage="+source.get("stage")+" width="+width+" height="+height+" direction="+source.get("direction")+" actual="+actual+" source="+source.get("tiles"));if(source.get("stage").getAsString().equals("loaded"))return;for(int x=0;x<width;x++){var root=host(world,BASE.east(x));var publication=root.publication();need(publication.visual().rows().size()==height&&publication.visual().width()==width&&publication.visual().column()==x,"complete immutable column projection");for(int row=0;row<height;row++)need(publication.visual().rows().get(row)==host(world,BASE.offset(x,-row,0)).settings(),"per-row material/settings projection");}}
 @SubscribeEvent public static void start(ServerStartedEvent event)throws Exception {if(!enabled())return;ServerLevel world=event.getServer().overworld();for(int x=199;x<=201;x++)for(int z=199;z<=201;z++){world.getChunk(x,z);world.setChunkForced(x,z,true);}var actor=new net.neoforged.neoforge.common.util.FakePlayer(world,new com.mojang.authlib.GameProfile(UUID.fromString("eb373367-bd70-46d9-a06d-fa83e57d0b34"),"SegmentedFixture")){@Override public boolean mayUseItemAt(BlockPos p,Direction side,ItemStack held){return !p.equals(denied)&&super.mayUseItemAt(p,side,held);}};actor.setGameMode(GameType.SURVIVAL);actor.setPos(BASE.getX()+.5,80,BASE.getZ()+.5);
  if(System.getProperty("vandorlabs.transmitterPhase").endsWith("write")){
   if(System.getProperty("vandorlabs.segmentedChannelReference")!=null){grid(world,BASE,1,1);SegmentedChannelChecks.run(world,host(world,BASE));updates=previousSource=previousNative=0;}
   var lines=Files.readAllLines(Paths.get(System.getProperty("vandorlabs.segmentedLifecycleReference")));int seen=0;
   for(String line:lines){var source=JsonParser.parseString(line).getAsJsonObject();int width=source.get("width").getAsInt(),height=source.get("height").getAsInt(),direction=source.get("direction").getAsInt();String stage=source.get("stage").getAsString();var root=host(world,BASE);
    switch(stage){case "loaded"->{clock(world,0);grid(world,BASE,1,1);host(world,BASE).loadWithComponents(TagParser.parseTag(source.get("input").getAsString()),world.registryAccess());}case "formed"->{clock(world,0);grid(world,BASE,width,height);}case "opening"->{root.configureAll(actor,ChannelList.EMPTY,7,false,false,-1,new NativeSegmentedDoorSettings(direction,false,1,0,true,2,true,NativeSegmentedDoorSettings.DEFAULT.glass,1));root.operate(actor,true);}case "reverse"->{clock(world,5);root.operate(actor,false);}case "part"->host(world,BASE.offset(width-1,1-height,0)).configurePart(actor,ChannelList.EMPTY,9,false,true,-1,new NativeSegmentedDoorSettings(direction,true,2,0,false,3,false,NativeSegmentedDoorSettings.DEFAULT.glass,2));default->throw new AssertionError("unknown source stage");}compare(world,source);int actualSource=source.get("updates").getAsInt();if(!stage.equals("formed")&&!stage.equals("loaded"))need(updates-previousNative==actualSource-previousSource,"source notification count for "+stage+" native="+(updates-previousNative)+" source="+(actualSource-previousSource));previousNative=updates;previousSource=actualSource;seen++;
   }need(seen==72,"full source corpus");grid(world,BASE,1,1);var mid=host(world,BASE);var midTag=mid.saveWithoutMetadata(world.registryAccess());midTag.putBoolean("SegmentedOpen",true);midTag.putDouble("SegmentedFrom",0);midTag.putLong("SegmentedStarted",0);midTag.putInt("SegmentedDuration",20);clock(world,7);mid.loadWithComponents(midTag,world.registryAccess());need(mid.pose(0)==.35&&mid.publication().motion().initialPose()==.35&&mid.initialPose()==0&&mid.saveWithoutMetadata(world.registryAccess()).getDouble("SegmentedFrom")==0,"loaded midstroke DTO samples current source pose without changing authoritative saved from");clock(world,0);grid(world,BASE,3,3);var root=host(world,BASE);long sequence=root.sequence();denied=BASE.offset(2,-2,0);boolean rejected=false;try{root.toggle(actor);}catch(IllegalArgumentException expected){rejected=true;}finally{denied=null;}need(rejected&&root.sequence()==sequence,"protected distant member rejects entire operation before mutation");observerFailure=true;try{root.operate(actor,true);throw new AssertionError("missing observer failure");}catch(IllegalStateException expected){need(root.targetOpen()&&root.publication().motion().targetOpen(),"throwing observer sees committed complete timeline");}finally{observerFailure=false;}
   var redstone=new NativeSegmentedDoorSettings(0,false,1,1,false,0,false,NativeSegmentedDoorSettings.DEFAULT.glass,0);root.configureAll(actor,ChannelList.of(72001),10,false,true,-1,redstone);rejected=false;try{root.toggle(actor);}catch(IllegalArgumentException expected){rejected=true;}need(rejected,"positive activation refuses manual ownership");root.setChannelLevel(15);root.tickServer();need(root.targetOpen(),"channel ON opens");root.setChannelLevel(0);root.tickServer();need(!root.targetOpen(),"channel OFF closes");root.configureAll(actor,ChannelList.EMPTY,10,false,true,-1,redstone.activation(2));need(root.targetOpen(),"OFF activation opens without signal");
   grid(world,SAVE,3,3);root=host(world,SAVE);root.configureAll(actor,ChannelList.of(72002),9,false,true,-1,new NativeSegmentedDoorSettings(2,true,2,0,true,3,true,NativeSegmentedDoorSettings.DEFAULT.glass,2));root.operate(actor,true);var saved=root.saveWithoutMetadata(world.registryAccess());CompoundTag opaque=new CompoundTag();opaque.putString("foreign","retained");saved.put("ForgeCaps",opaque);root.loadWithComponents(saved,world.registryAccess());need(root.publication().motion().duration()==27,"saved horizontal timeline uses span");
   var bad=saved.copy();bad.putInt("SegmentedColumn",31);bad.putInt("SegmentedColumns",1);bad.putString("UnknownFuture","opaque");var failed=new NativeSegmentedDoorEntity(type,SAVE,block.defaultBlockState());failed.loadWithComponents(bad,world.registryAccess());need(failed.inert()&&!failed.isChannelMemberActive(),"failed snapshot is inert");need(failed.saveWithoutMetadata(world.registryAccess()).equals(bad),"failed snapshot retains original full data");
   var projection=root.getUpdateTag(world.registryAccess());need(!projection.contains("ForgeCaps")&&!projection.contains("UnknownFuture"),"opaque saved data excluded from visual packet");
  }else{var root=host(world,SAVE);need(root!=null&&root.formed()&&root.height()==3&&root.columnsCount()==3&&root.settings().direction==2&&root.settings().position==2&&root.targetOpen(),"subsequent process reload retains real native span and settings");need(root.saveWithoutMetadata(world.registryAccess()).getCompound("ForgeCaps").getString("foreign").equals("retained"),"opaque foreign data survives restart");need(root.getRedstoneChannels().equals(ChannelList.of(72002)),"channel save survives restart");for(int row=0;row<3;row++)need(host(world,SAVE.below(row)).root()==root,"real loaded member ownership after restart");}
  System.out.println("[vandorlabs][segmented-lifecycle] "+(System.getProperty("vandorlabs.transmitterPhase").endsWith("write")?"write":"read")+" PASS checks="+checks);event.getServer().halt(false);
 }
}
